local fineAvailable = type(ui.grid) == "function"
local fineRows

local function drawFine()
    if not fineRows then
        fineRows = {}
        for index, tile in ipairs(fineTiles) do
            local width = tile[3]
            local pixels = decode(tile[5])
            local rows = {}
            for first = 1, #pixels, width do
                rows[#rows+1] = {string.byte(pixels, first, first+width-1)}
            end
            fineRows[index] = rows
        end
    end
    for index, tile in ipairs(fineTiles) do
        local ok, result = pcall(ui.grid, tile[1], tile[2], tile[4], tile[4], fineRows[index])
        if not ok or result == false then
            fineAvailable, fineRows = false, nil
            return false
        end
    end
    return true
end

local gridPatches
if type(ui.grid) == "function" then
    local pixels = decode("")
    gridPatches = {}
    local offset = 1
    while offset <= #pixels do
        local px, py, scale = string.byte(pixels, offset, offset+2)
        local width, height = 24/scale, 20/scale
        local rows = {}
        for start = offset+3, offset+2+width*height, width do
            rows[#rows+1] = {string.byte(pixels, start, start+width-1)}
        end
        gridPatches[#gridPatches+1] = {x = px*2, y = py*2, scale = scale, rows = rows}
        offset = offset+3+width*height
    end
end
