local function actorInk(index)
    return index < 16 and 224+index or 226+index
end

local inKitchen, crossing = false, false
local function courier()
    local threshold = inKitchen and 144 or 130
    local depth = math.max(0, math.min(1, (y-threshold)/(233-threshold)))
    local farHeight = inKitchen and 56 or 49
    local scale = (farHeight + depth*(100-farHeight))/1.852
    local sine, cosine = math.sin(facing), math.cos(facing)
    local stride = walking and math.sin(step/3.2)*0.075 or 0
    local vertices, faces = {}, {}
    for i = 1,#actorPoints,3 do
        local a,b,c = string.byte(actorPoints,i,i+2)
        local ax, ay, az = (a-128)/128, b/128, (c-128)/128
        local leg = math.max(0,1-ay/0.85)
        az = az + (ax < 0 and stride or -stride)*leg
        local depth = az*cosine-ax*sine
        local size = scale*4.5/(4.5+depth)
        vertices[#vertices+1] = {
            math.floor(x+(ax*cosine+az*sine)*size),
            math.floor(y-(ay+depth*0.22)*size),
            depth
        }
    end
    for i = 1,#actorTriangles,7 do
        local al,ah,bl,bh,cl,ch,ink = string.byte(actorTriangles,i,i+6)
        local a,b,c = vertices[al+ah*256+1],vertices[bl+bh*256+1],vertices[cl+ch*256+1]
        local area = (b[1]-a[1])*(c[2]-a[2])-(b[2]-a[2])*(c[1]-a[1])
        if area < 0 then
            faces[#faces+1] = {a,b,c,a[3]+b[3]+c[3],actorInk(ink)}
        end
    end
    table.sort(faces,function(a,b) return a[4]>b[4] end)
    for _, face in ipairs(faces) do
        local a,b,c = face[1],face[2],face[3]
        ui.trisfill(a[1],a[2],b[1],b[2],c[1],c[2],face[5])
    end
end

local function held(button)
    local value = ui.btn(button, 0)
    return value == true or (type(value) == "number" and value > 0)
end

local function drawImage(image, minX, maxX, colors)
    local scale = 2
    for i = 1, #image, 5 do
        local a,b,c,d,color = string.byte(image,i,i+4)
        if (c+1)*scale-1 >= minX and a*scale <= maxX then
            local ink = colors and colors[color] or (not colors and color-1)
            if ink and (d+1)*scale-1 >= 16 then
                ui.rectfill(a*scale,math.max(16,b*scale),(c+1)*scale-1,(d+1)*scale-1,ink)
            end
        end
    end
end


function update()
    ui.cls(0)

    for i, color in ipairs(actorPalette) do ui.palset(actorInk(i-1), color) end
    local dx = (held(RIGHT or 2) and 1 or 0) - (held(LEFT or 4) and 1 or 0)
    local dy = (held(DOWN or 3) and 1 or 0) - (held(UP or 1) and 1 or 0)
    if dy >= 0 then crossing = false end
    if crossing and dy < 0 then dy = 0 end
    if dy < 0 then
        facing = math.pi + dx*0.7
    elseif dy > 0 then
        facing = -dx*0.7
    elseif dx ~= 0 then
        facing = -dx*1.15
    end
    walking = dx ~= 0 or dy ~= 0
    if walking then step = step + 1 end
    -- The sofa touches the wall. Follow its front edge to reach the doorway.
    local function walkable(px, py)
        if inKitchen then
            return py >= 144 and py <= 233 and px >= 145 and px <= 312 + (py-144)*0.9
        end
        return px >= 48 and px <= 448 and py >= 130 and py <= 230
            and (px >= 218 or py >= 216 - (px - 48) * 0.19)
    end
    local nextX, nextY = x + dx * 1.95, y + dy * 1.75
    if walkable(nextX, y) then x = nextX end
    if walkable(x, nextY) then y = nextY end
    local status = inKitchen and "COZINHA" or "SALA"
    if inKitchen then
        if x >= 202 and x <= 270 and y <= 158 then
            status = "PASSAGEM PARA SALA"
            if dy < 0 and not crossing and y <= 146 then
                crossing = true
                inKitchen, x, y, facing, status = false, 273-(x-236)*0.55, 151, 0, "SALA"
            end
        end
    elseif x >= 247 and x <= 304 and y <= 151 then
        status = kitchenBitmap and "PASSAGEM PARA COZINHA" or "COZINHA AUSENTE"
        if dy < 0 and not crossing and y <= 138 and kitchenBitmap then
            crossing = true
            inKitchen, x, y, facing, status = true, 236-(x-273)*0.55, 154, 0, "COZINHA"
        end
    elseif x >= 218 and x < 238 and y <= 150 then
        status = "CORREDOR EM BREVE"
    elseif x >= 392 and y <= 160 then
        status = "FRENTE EM BREVE"
    elseif x >= 168 and x <= 245 and y >= 221 then
        status = "ESCRITORIO / PORAO EM BREVE"
    end
    local strips = inKitchen and kitchenBitmap or bitmap
    local native = not not strips
    for i, color in ipairs(native and bitmapPalette or Palette) do ui.palset(i-1, color) end
    ui.palset(240, 0)
    ui.palset(241, 32767)
    if native then
        for index, strip in ipairs(strips) do
            local ok, result = pcall(ui.spr, strip, 0, (index-1)*82)
            if not ok or result == false then
                if inKitchen then
                    kitchenBitmap, inKitchen, x, y = nil, false, 273, 158
                    status = "ERRO COZINHA"
                else
                    bitmap = nil
                end
                native = false
                ui.cls(0)
                for i, color in ipairs(Palette) do ui.palset(i-1, color) end
                break
            end
        end
    end
    local fine = false
    if not native then
        drawImage(detailedBackground, 0, 479)
        fine = fineAvailable and drawFine()
    end
    ui.rectfill(0,0,479,15,240)
    ui.print("8.6 "..status,8,3,241)
    if not native and not fine and gridPatches then
        for _, patch in ipairs(gridPatches) do
            if not pcall(ui.grid, patch.x, patch.y, patch.scale, patch.scale, patch.rows) then
                gridPatches = nil
                break
            end
        end
    end
    courier()
    if not inKitchen and y <= 159 then drawImage(detailedSofa, x-24, x+24, native and sofaColors or nil) end
end
